/* LeetCode supplies the doubly-linked-list Node definition. */
class Solution {
public:
    vector<int> toArray(Node* node) {
        if (!node) return {};
        while (node->prev) node = node->prev;
        vector<int> result;
        while (node) {
            result.push_back(node->val);
            node = node->next;
        }
        return result;
    }
};
